def SeminormSubspaceSimilarities (p : RightSeminorm X) (n : ℕ) : Prop :=
  ∀ E F : Submodule Hᵐᵒᵖ X, Module.finrank Hᵐᵒᵖ E = n → Module.finrank Hᵐᵒᵖ F = n →
    ∃ T : E ≃ₗ[Hᵐᵒᵖ] F, ∃ c : ℝ, 0 < c ∧ ∀ x : E, p (T x : X) = c * p (x : X)

